import{_ as r,o as a,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph User + Dev Monthly - September 2025","description":"","frontmatter":{"title":"Ceph User + Dev Monthly - September 2025","date":"2025-09-17T00:00:00.000Z","updated":"2025-09-18T00:00:00.000Z","tags":["Ceph","Balancer模块","PG remapping","remediation scripts","用户反馈"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_User_+_Dev_Monthly_-_September_2025.md","filePath":"posts/2025/Ceph_User_+_Dev_Monthly_-_September_2025.md","lastUpdated":1780459816000}'),l={name:"posts/2025/Ceph_User_+_Dev_Monthly_-_September_2025.md"};function n(i,e,s,p,d,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<p>本次Ceph用户和开发者月度会议主要讨论了Balancer模块的功能增强，特别是针对PG remapping问题的解决方案。以下是会议的主要内容：</p><h2 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h2><ul><li><strong>会议主题</strong>：Balancer模块功能增强讨论（针对PG remapping问题）</li><li><strong>主持人</strong>：Laura</li><li><strong>参会人员</strong>：Laura, Dan Vanderster, Alexander, Frederick, Enrico等社区成员</li></ul><h2 id="主要讨论内容" tabindex="-1">主要讨论内容 <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;主要讨论内容&quot;">​</a></h2><ul><li><strong>当前问题背景</strong>：讨论了两个非官方脚本：<code>upmap_remapper</code>（Python实现）和<code>pg_remapper</code>（Go实现），它们用于解决PG卡在<code>remapped</code>和<code>backfilling</code>状态的问题。</li><li><strong>核心用例分析</strong>：包括容量变更（添加/移除主机或机架、更改CRUSH规则或可调参数、排空主机）、恢复优先级问题和OSD map修剪问题。</li><li><strong>现有解决方案比较</strong>：比较了<code>upmap_remapper</code>、<code>pg_remapper</code>和<code>JJ balancer</code>的主要功能和额外功能。</li><li><strong>提案讨论</strong>： <ul><li><strong>短期方案（Umbrella版本）</strong>：添加新的<code>ceph pg remap undo</code>命令，提供官方支持，而不修改balancer模块的现有行为。</li><li><strong>长期方案</strong>：修改balancer模块的行为，当misplaced比例超过阈值时自动执行部分remapping，并考虑工作时间窗口。</li></ul></li><li><strong>技术细节讨论</strong>：包括<code>undo</code>命令功能和与balancer的交互。</li></ul><h2 id="决策事项" tabindex="-1">决策事项 <a class="header-anchor" href="#决策事项" aria-label="Permalink to &quot;决策事项&quot;">​</a></h2><ol><li><strong>优先实现方案</strong>：首先实现<code>ceph pg remap undo</code>命令，保持与现有脚本相同的核心功能。</li><li><strong>后续开发计划</strong>：添加基础命令及测试用例，增强balancer模块的智能行为，采用分阶段验证策略。</li><li><strong>测试场景</strong>：包括大规模容量增减、CRUSH规则变更和OSD权重调整。</li></ol><h2 id="行动计划" tabindex="-1">行动计划 <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;行动计划&quot;">​</a></h2><ol><li><strong>Laura</strong>：深入研究现有脚本实现，评估添加新命令的技术方案，设计测试用例。</li><li><strong>社区成员</strong>：提供具体的使用场景和命令行示例，创建关于CRUSH reweight dry run功能的feature tracker。</li><li><strong>跟踪机制</strong>：通过现有feature ticket继续讨论，后续userdev会议跟进进展。</li></ol><h2 id="其他建议" tabindex="-1">其他建议 <a class="header-anchor" href="#其他建议" aria-label="Permalink to &quot;其他建议&quot;">​</a></h2><ul><li>考虑添加CRUSH操作预测功能（dry run）。</li><li>加强文档说明新命令的使用场景和注意事项。</li><li>在实现中考虑添加警告机制（当需要关闭balancer时）。</li></ul><p>本次会议对Balancer模块的功能增强进行了深入讨论，并制定了详细的开发计划，旨在提高Ceph集群的稳定性和性能。</p>',12)])])}const g=r(l,[["render",n]]);export{h as __pageData,g as default};
